import {
    Table,
    CalendarDateTimeColumn,
    GuidColumn,
    IntegerColumn,
    ReferenceColumn,
    SystemClassNameColumn,
} from '../../db'

/**
 * Business Calendar Entry - a single start/end block on a calendar. This is the base
 * class that `cmn_schedule_span` extends; the `index0`-`index9` and `counter` columns
 * are the platform's expansion cache for recurring entries and are maintained by the
 * schedule engine rather than authored.
 */
export const business_calendar_span = Table({
    extensible: true,
    label: 'Business Calendar Entry',
    name: 'business_calendar_span',
    schema: {
        calendar: ReferenceColumn({
            label: 'Calendar',
            referenceTable: 'business_calendar',
        }),
        counter: IntegerColumn({
            label: 'Counter',
        }),
        end: CalendarDateTimeColumn({
            label: 'End',
        }),
        index0: IntegerColumn({ label: 'Index0' }),
        index1: IntegerColumn({ label: 'Index1' }),
        index2: IntegerColumn({ label: 'Index2' }),
        index3: IntegerColumn({ label: 'Index3' }),
        index4: IntegerColumn({ label: 'Index4' }),
        index5: IntegerColumn({ label: 'Index5' }),
        index6: IntegerColumn({ label: 'Index6' }),
        index7: IntegerColumn({ label: 'Index7' }),
        index8: IntegerColumn({ label: 'Index8' }),
        index9: IntegerColumn({ label: 'Index9' }),
        span_name: ReferenceColumn({
            label: 'Name',
            referenceTable: 'business_calendar_span_name',
        }),
        start: CalendarDateTimeColumn({
            label: 'Start',
        }),
        sys_class_name: SystemClassNameColumn({
            default: 'javascript:current.getTableName();',
            label: 'Class',
            maxLength: 80,
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
    },
})
